function storeUi() {
  byId('storeUi').innerHTML = `<div class="overlay" id="overlay" hidden></div><section class="drawer" id="productDrawer" role="dialog" aria-modal="true" aria-labelledby="detailName" hidden><div class="drawer-head"><span>Choose your gift</span><button class="close-btn" data-close type="button" aria-label="Close">×</button></div><div class="product-detail-media"><img id="detailImage" alt=""></div><div class="product-detail-content"><p class="kicker" id="detailCategory"></p><h2 id="detailName"></h2><p class="detail-price" id="detailPrice"></p><p class="detail-desc" id="detailDesc"></p><form id="productForm"><label>Package size<select id="packageSize"><option value="Simple">Simple — base price</option><option value="Signature">Signature — + UGX 35,000</option><option value="Grand">Grand — + UGX 80,000</option></select></label><label id="choiceLabel"><span id="choiceText">Style</span><select id="productChoice"></select></label><label>Gift message <span>optional</span><textarea id="giftMessage" rows="3" maxlength="160" placeholder="Write a short note for the card"></textarea></label><button class="btn btn-orange full" type="submit">Add to bag · <span id="addPrice"></span></button></form></div></section><aside class="drawer" id="bagDrawer" aria-labelledby="bagTitle" hidden><div class="drawer-head"><h2 id="bagTitle">Your bag</h2><button class="close-btn" data-close type="button" aria-label="Close bag">×</button></div><div class="bag-items" id="bagItems"></div><div class="empty-bag" id="emptyBag"><b>◇</b><h3>Your bag is waiting</h3><p>Choose something thoughtful and it will appear here.</p><a class="btn btn-green" href="shop.html">Browse gifts</a></div><div class="checkout" id="checkout" hidden><form id="checkoutForm"><h3>Delivery details</h3><div class="field-row"><label>Your name<input name="customerName" autocomplete="name" required></label><label>Your phone<input name="customerPhone" inputmode="tel" autocomplete="tel" required></label></div><div class="field-row"><label>Recipient’s name<input name="recipientName" required></label><label>Recipient’s phone<input name="recipientPhone" inputmode="tel" required></label></div><label>Delivery area<select name="zone" id="deliveryZone" required><option value="">Choose an area</option>${Object.entries(deliveryFees).map(([name,fee])=>`<option value="${name}">${name} — ${fee?money(fee):'quote needed'}</option>`).join('')}</select></label><label>Address & landmark<textarea name="address" rows="2" required></textarea></label><label>Delivery date<input name="date" id="deliveryDate" type="date" required></label><label>Preferred payment method<select name="payment" required><option value="">Choose a method</option><option>MTN Mobile Money</option><option>Airtel Money</option><option>Bank transfer</option><option>Approved cash on delivery</option></select></label><label class="check"><input name="surprise" type="checkbox"> Keep it a surprise—contact me first</label><div class="totals"><div><span>Gifts</span><span id="subtotal">UGX 0</span></div><div><span>Delivery</span><span id="deliveryFee">Choose area</span></div><div class="grand"><strong>Total</strong><strong id="total">UGX 0</strong></div></div><div class="payment-safety"><strong>Secure payment</strong><span>We first confirm your order reference, availability and final total. Never send a PIN, OTP or password.</span><a href="payments.html">Read the payment guide →</a></div><button class="btn btn-green full" type="submit">Create order &amp; WhatsApp</button><p class="fine-print">Payment details are shared privately after we confirm the order.</p></form></div></aside><div class="toast" id="toast" role="status" aria-live="polite"></div>`;
  byId('storeUi').insertAdjacentHTML('afterbegin', `<a class="floating-whatsapp" href="https://wa.me/${WHATSAPP}?text=${encodeURIComponent("Hello GiftHub UG, I'd like help choosing a gift.")}" target="_blank" rel="noopener" aria-label="Chat with GiftHub UG on WhatsApp"><b>WhatsApp</b><span>Need help?</span></a>`);
}

function productCard(product) {
  return `<article class="product-card"><div class="product-media" data-product="${product.id}" tabindex="0" role="button" aria-label="Choose ${esc(product.name)}"><img src="${product.image}" alt="${esc(product.name)}" loading="lazy">${product.tag?`<span class="pill">${esc(product.tag)}</span>`:''}<button class="quick-btn" type="button" data-product="${product.id}" aria-label="Add ${esc(product.name)}">+</button></div><div class="product-body"><span class="product-category">${esc(product.occasion)}</span><h3>${esc(product.name)}</h3><p>${esc(product.desc)}</p><div class="product-bottom"><strong>From ${money(product.price)}</strong><button type="button" data-product="${product.id}">Choose</button></div></div></article>`;
}

function renderLists() {
  document.querySelectorAll('[data-product-list]').forEach(list => {
    const type = list.dataset.productList;
    let matches = type === 'all' ? products : type === 'featured' ? products.filter(p=>['birthday-bliss','graduate-glow','perfume-rose-signature','skin-glow-box','phone-essentials-box','photo-board-small','wood-watch-box','signature-cake'].includes(p.id)) : products.filter(p=>p.category===type);
    if (type === 'all') matches = matches.filter(p => {
      const inBudget = state.budget==='All' || (state.budget==='Under 75K'&&p.price<75000) || (state.budget==='75K–150K'&&p.price>=75000&&p.price<=150000) || (state.budget==='150K+'&&p.price>150000);
      const forRecipient = state.recipient==='All' || p.recipient===state.recipient || p.recipient==='Anyone';
      return (state.filter==='All'||p.category===state.filter) && inBudget && forRecipient && `${p.name} ${p.category} ${p.occasion} ${p.recipient} ${p.desc}`.toLowerCase().includes(state.search.toLowerCase());
    });
    list.innerHTML = matches.map(productCard).join('') || '<p>No gifts match your search.</p>';
  });
}

function renderOccasions() {
  const root = byId('occasionSections');
  if (!root) return;
  const slug = name => name.toLowerCase().replace(/\s+/g,'-');
  root.innerHTML = Object.entries(occasionCopy).map(([name,copy]) => `<section class="occasion-group" id="${slug(name)}"><div class="occasion-group-head"><div><p class="kicker">${esc(name)} gifts</p><h2>${esc(name)}</h2></div><p>${esc(copy)}</p></div><div class="product-grid light-grid">${products.filter(p=>p.occasion===name).slice(0,4).map(productCard).join('')}</div></section>`).join('');
}

function setupShopFilters() {
  const root = byId('productFilters'); if (!root) return;
  const cats = ['All','Hampers','Perfumes','Skincare','Tech Gifts','Jewellery','Thanksgiving','Room Styling','Flowers','Cakes','Personalised','For Her','For Him','Baby Gifts','Wellness','Food & Treats','Corporate'];
  root.innerHTML = cats.map(c=>`<button class="chip ${c==='All'?'active':''}" data-filter="${c}" type="button">${c}</button>`).join('');
  root.addEventListener('click', e => { const b=e.target.closest('[data-filter]'); if(!b)return; state.filter=b.dataset.filter; root.querySelectorAll('.chip').forEach(x=>x.classList.toggle('active',x===b)); renderLists(); });
  byId('budgetFilter')?.addEventListener('change',e=>{state.budget=e.target.value;renderLists();});
  byId('recipientFilter')?.addEventListener('change',e=>{state.recipient=e.target.value;renderLists();});
  byId('productSearch').addEventListener('input', e => { state.search=e.target.value; renderLists(); });
}

function show(id) { byId('overlay').hidden=false; byId(id).hidden=false; document.body.classList.add('drawer-open'); const f=byId(id).querySelector('button,input,select,textarea,a'); if(f)setTimeout(()=>f.focus(),20); }
function closeAll() { byId('overlay').hidden=true; byId('productDrawer').hidden=true; byId('bagDrawer').hidden=true; document.body.classList.remove('drawer-open'); }
function openProduct(id) {
  const p=products.find(x=>x.id===id); if(!p)return; state.active=p;
  byId('detailImage').src=p.image; byId('detailImage').alt=p.name; byId('detailCategory').textContent=`${p.occasion} · ${p.category}`; byId('detailName').textContent=p.name; byId('detailDesc').textContent=p.desc; byId('detailPrice').textContent=`From ${money(p.price)}`; byId('choiceText').textContent=p.choice; byId('productChoice').innerHTML=p.options.map(o=>`<option>${esc(o)}</option>`).join(''); byId('packageSize').value='Simple'; byId('giftMessage').value=''; updateAddPrice(); show('productDrawer');
}
function activeBasePrice() { if(!state.active)return 0; return state.active.choicePrices?.[byId('productChoice').value] ?? state.active.price; }
function updateAddPrice() { if(state.active) byId('addPrice').textContent=money(activeBasePrice()+packageExtras[byId('packageSize').value]); }
function saveBag() { localStorage.setItem('gifthub-ug-bag-v1',JSON.stringify(state.bag)); renderBag(); }
function renderBag() {
  const count=state.bag.reduce((s,i)=>s+i.quantity,0); byId('bagCount').textContent=count; byId('emptyBag').hidden=state.bag.length>0; byId('checkout').hidden=!state.bag.length;
  byId('bagItems').innerHTML=state.bag.map((item,i)=>`<div class="bag-item"><img src="${item.image}" alt=""><div><h3>${esc(item.name)}</h3><p>${esc(item.package)} · ${esc(item.choice)}${item.message?` · “${esc(item.message)}”`:''}</p><div class="qty"><button type="button" data-qty="${i}" data-delta="-1">−</button><span>${item.quantity}</span><button type="button" data-qty="${i}" data-delta="1">+</button></div></div><div><strong>${money(item.unitPrice*item.quantity)}</strong><br><button class="remove" data-remove="${i}" type="button">Remove</button></div></div>`).join(''); updateTotals();
}
function updateTotals() { const sub=state.bag.reduce((s,i)=>s+i.unitPrice*i.quantity,0); const zone=byId('deliveryZone')?.value||''; const fee=deliveryFees[zone]||0; byId('subtotal').textContent=money(sub); byId('deliveryFee').textContent=!zone?'Choose area':zone==='Other area'?'To be confirmed':money(fee); byId('total').textContent=zone==='Other area'?`${money(sub)} + delivery`:money(sub+fee); }
function notify(message) { const t=byId('toast'); t.textContent=message; t.classList.add('show'); clearTimeout(notify.timer); notify.timer=setTimeout(()=>t.classList.remove('show'),2200); }
function orderReference() {
  const d=new Date();
  const date=`${String(d.getFullYear()).slice(-2)}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}`;
  return `GHU-${date}-${Math.random().toString(36).slice(2,8).toUpperCase()}`;
}

function bindStore() {
  document.addEventListener('click', e => {
    const product=e.target.closest('[data-product]'); if(product){openProduct(product.dataset.product);return;}
    if(e.target.closest('[data-close]')||e.target===byId('overlay')) closeAll();
    const wa=e.target.closest('[data-whatsapp]'); if(wa){ e.preventDefault(); window.open(`https://wa.me/${WHATSAPP}?text=${encodeURIComponent("Hello GiftHub UG, I'd like help choosing a gift.")}`,'_blank','noopener'); }
  });
  document.addEventListener('keydown', e => { if(e.key==='Escape')closeAll(); if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-product]')){e.preventDefault();openProduct(e.target.dataset.product);} });
  byId('openBag').addEventListener('click',()=>show('bagDrawer'));
  byId('themeToggle').addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('gifthub-ug-theme',next);});
  byId('packageSize').addEventListener('change',updateAddPrice);
  byId('productChoice').addEventListener('change',updateAddPrice);
  byId('productForm').addEventListener('submit',e=>{e.preventDefault();const p=state.active;const pack=byId('packageSize').value;const item={id:p.id,name:p.name,image:p.image,package:pack,choice:byId('productChoice').value,message:byId('giftMessage').value.trim(),unitPrice:activeBasePrice()+packageExtras[pack],quantity:1};const old=state.bag.find(x=>x.id===item.id&&x.package===item.package&&x.choice===item.choice&&x.message===item.message);old?old.quantity++:state.bag.push(item);saveBag();closeAll();notify(`${p.name} added to your bag`);});
  byId('bagItems').addEventListener('click',e=>{const q=e.target.closest('[data-qty]');const r=e.target.closest('[data-remove]');if(q){const i=Number(q.dataset.qty);state.bag[i].quantity+=Number(q.dataset.delta);if(state.bag[i].quantity<1)state.bag.splice(i,1);saveBag();}if(r){state.bag.splice(Number(r.dataset.remove),1);saveBag();}});
  byId('deliveryZone').addEventListener('change',updateTotals);
  byId('checkoutForm').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget);const zone=d.get('zone');const sub=state.bag.reduce((s,i)=>s+i.unitPrice*i.quantity,0);const fee=deliveryFees[zone]||0;const ref=orderReference();localStorage.setItem('gifthub-ug-last-order',ref);const lines=state.bag.map((i,n)=>`${n+1}. ${i.name} × ${i.quantity} — ${money(i.unitPrice*i.quantity)}\n   ${i.package} · ${i.choice}${i.message?` · Card: “${i.message}”`:''}`);const total=zone==='Other area'?`${money(sub)} + delivery quote`:money(sub+fee);const msg=`Hello GiftHub UG! I'd like to place this order.\n\nORDER REFERENCE: ${ref}\n\n${lines.join('\n')}\n\nGifts: ${money(sub)}\nDelivery: ${zone==='Other area'?'Quote needed':money(fee)}\nTOTAL: ${total}\nPAYMENT PREFERENCE: ${d.get('payment')}\n\nFROM\n${d.get('customerName')} · ${d.get('customerPhone')}\n\nDELIVER TO\n${d.get('recipientName')} · ${d.get('recipientPhone')}\n${d.get('address')}, ${zone}\nDate: ${d.get('date')}\n${d.get('surprise')?'Please keep this a surprise and contact me first.':'You may contact the recipient for delivery.'}\n\nPlease confirm availability, final total and the correct payment details before I pay. I will use ${ref} as my payment reference.`;window.open(`https://wa.me/${WHATSAPP}?text=${encodeURIComponent(msg)}`,'_blank','noopener');});
}

function setupConcierge() {
  const form=byId('conciergeForm'); if(!form)return;
  form.addEventListener('submit',e=>{
    e.preventDefault();
    const d=new FormData(form);
    const message=`Hello GiftHub UG! Please plan a gift for me.\n\nOCCASION: ${d.get('occasion')}\nRECIPIENT: ${d.get('recipient')}\nAGE / STAGE: ${d.get('age')}\nBUDGET: ${d.get('budget')}\nSTYLE: ${d.get('style')}\nDELIVERY: ${d.get('delivery')}\n\nWHAT THEY LIKE\n${d.get('likes')||'Open to your ideas'}\n\nPERSONALISATION\n${d.get('personalisation')||'Please advise'}\n\nMY NAME: ${d.get('name')}\nPHONE: ${d.get('phone')}`;
    window.open(`https://wa.me/${WHATSAPP}?text=${encodeURIComponent(message)}`,'_blank','noopener');
  });
}

async function setupReviews() {
  const grid=byId('reviewsGrid');
  if (grid) {
    try {
      const response=await fetch('reviews.json',{cache:'no-store'});
      if(!response.ok) throw new Error('Review feed unavailable');
      const data=await response.json();
      const reviews=Array.isArray(data.reviews)?data.reviews:[];
      grid.innerHTML=reviews.length?reviews.map(review=>`<article class="review-card"><div class="review-stars" aria-label="${Number(review.rating)} out of 5 stars">${'★'.repeat(Number(review.rating))}${'☆'.repeat(5-Number(review.rating))}</div><blockquote>“${esc(review.text)}”</blockquote><div><strong>${esc(review.name)}</strong><span>${esc(review.occasion||'Completed order')} · Customer purchase</span></div></article>`).join(''):`<div class="review-empty"><span>New shop, honest start</span><h2>Be one of our first customers to share feedback.</h2><p>We check every review against a completed order before it appears. No invented ratings and no anonymous testimonials.</p><a class="btn btn-orange" href="#leave-review">Share your experience</a></div>`;
    } catch (_) {
      grid.innerHTML='<div class="review-empty"><h2>Reviews are temporarily unavailable.</h2><p>Please try again shortly or send your feedback on WhatsApp.</p></div>';
    }
  }
  const form=byId('reviewForm'); if(!form)return;
  form.addEventListener('submit',e=>{
    e.preventDefault();
    const d=new FormData(form);
    const message=`Hello GiftHub UG! I would like to share feedback about my completed order.\n\nORDER REFERENCE: ${d.get('orderRef')}\nNAME TO DISPLAY: ${d.get('name')}\nRATING: ${d.get('rating')}/5\nOCCASION: ${d.get('occasion')}\nREVIEW:\n${d.get('review')}\n\nI consent to GiftHub UG publishing this review after matching it to my order.`;
    window.open(`https://wa.me/${WHATSAPP}?text=${encodeURIComponent(message)}`,'_blank','noopener');
  });
}

function registerTools() {
  const ctx=document.modelContext;if(!ctx?.registerTool)return;const life=new AbortController();const reg=t=>Promise.resolve(ctx.registerTool(t,{signal:life.signal})).catch(()=>{});
  reg({name:'list_gifts',title:'List gifts',description:'List GiftHub UG gifts with category, occasion, recipient and UGX prices.',inputSchema:{type:'object',properties:{occasion:{type:'string'},category:{type:'string'},recipient:{type:'string'},max_price_ugx:{type:'number'}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input={}){return{gifts:products.filter(p=>(!input.occasion||p.occasion===input.occasion)&&(!input.category||p.category===input.category)&&(!input.recipient||p.recipient===input.recipient||p.recipient==='Anyone')&&(!input.max_price_ugx||p.price<=input.max_price_ugx)).map(p=>({id:p.id,name:p.name,occasion:p.occasion,category:p.category,recipient:p.recipient,price_ugx:p.price}))}}});
  reg({name:'add_gift_to_bag',title:'Add gift to bag',description:'Add one available gift to the visible GiftHub UG shopping bag.',inputSchema:{type:'object',properties:{product_id:{type:'string'},package:{type:'string',enum:['Simple','Signature','Grand']},quantity:{type:'integer',minimum:1,maximum:10},message:{type:'string',maxLength:160}},required:['product_id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const p=products.find(x=>x.id===input.product_id);if(!p)throw new Error('Gift not found.');const pack=input.package||'Simple';const qty=input.quantity||1;state.bag.push({id:p.id,name:p.name,image:p.image,package:pack,choice:p.options[0],message:String(input.message||''),unitPrice:p.price+packageExtras[pack],quantity:qty});saveBag();return{added:true,product_id:p.id,quantity:qty,bag_count:state.bag.reduce((s,i)=>s+i.quantity,0)}}});
}

document.documentElement.dataset.theme=localStorage.getItem('gifthub-ug-theme')||localStorage.getItem('kin-kind-theme')||(window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');
header(); footer(); storeUi(); renderOccasions(); setupShopFilters(); renderLists(); bindStore(); renderBag(); setupConcierge(); setupReviews(); registerTools();
const today=new Date();const tomorrow=new Date(today);tomorrow.setDate(today.getDate()+1);byId('deliveryDate').min=today.toISOString().slice(0,10);byId('deliveryDate').value=tomorrow.toISOString().slice(0,10);
